-- Hand-written: integrity backstops Prisma cannot express. The tenant pattern repeats the
-- kernel's single rule (parseTenantId); the others repeat the module's domain rules.
ALTER TABLE "identity"."account"
  ADD CONSTRAINT "account_tenant_id_check" CHECK ("tenant_id" ~ '^[a-z][a-z0-9-]{1,31}$'),
  ADD CONSTRAINT "account_population_check" CHECK ("population" IN ('platform-operator', 'tenant-staff', 'portal-user')),
  ADD CONSTRAINT "account_source_check" CHECK ("source" IN ('directory', 'local')),
  -- A directory account exists only because its person signed in, so it always has a subject.
  ADD CONSTRAINT "account_directory_subject_check" CHECK ("source" = 'local' OR "subject" IS NOT NULL),
  ADD CONSTRAINT "account_subject_check" CHECK ("subject" IS NULL OR char_length("subject") > 0),
  ADD CONSTRAINT "account_username_check" CHECK (char_length("username") > 0 AND "username" = lower("username")),
  ADD CONSTRAINT "account_status_check" CHECK ("status" IN ('active', 'disabled')),
  ADD CONSTRAINT "account_version_check" CHECK ("version" >= 1);

ALTER TABLE "identity"."session"
  ADD CONSTRAINT "session_token_hash_check" CHECK (octet_length("token_hash") = 32),
  ADD CONSTRAINT "session_expiry_check" CHECK ("expires_at" > "created_at");

ALTER TABLE "identity"."role"
  ADD CONSTRAINT "role_tenant_id_check" CHECK ("tenant_id" ~ '^[a-z][a-z0-9-]{1,31}$'),
  ADD CONSTRAINT "role_key_check" CHECK ("key" ~ '^[a-z0-9]+(-[a-z0-9]+)*$'),
  ADD CONSTRAINT "role_kind_check" CHECK ("kind" IN ('system', 'default', 'custom')),
  ADD CONSTRAINT "role_scope_check" CHECK ("scope" IN ('platform', 'tenant', 'site')),
  ADD CONSTRAINT "role_permission_keys_check" CHECK (
    "permission_keys" IS NOT NULL
    AND array_position("permission_keys", NULL) IS NULL
    AND ("kind" <> 'system' OR cardinality("permission_keys") = 0)
  ),
  ADD CONSTRAINT "role_version_check" CHECK ("version" >= 1);

ALTER TABLE "identity"."role_assignment"
  ADD CONSTRAINT "role_assignment_level_check" CHECK ("level" IN ('platform', 'tenant', 'site')),
  -- A site grant names its site; a tenant or platform grant names none and never descends.
  ADD CONSTRAINT "role_assignment_site_check" CHECK (
    ("level" = 'site') = ("site_id" IS NOT NULL)
    AND ("level" = 'site' OR NOT "include_descendants")
  );

-- Grants. The group role "phoenix_app" is created by the cluster bootstrap, never by a
-- migration. A session ends by deleting its row. Roles and assignments are read here and
-- written by the role use cases (slice 1.6); nothing deletes an account.
GRANT USAGE ON SCHEMA "identity" TO "phoenix_app";
GRANT SELECT, INSERT, UPDATE ("subject", "status", "version", "updated_at") ON TABLE "identity"."account" TO "phoenix_app";
GRANT SELECT, INSERT, DELETE ON TABLE "identity"."session" TO "phoenix_app";
GRANT SELECT, INSERT, UPDATE ("permission_keys", "version", "updated_at") ON TABLE "identity"."role" TO "phoenix_app";
GRANT SELECT, INSERT, DELETE ON TABLE "identity"."role_assignment" TO "phoenix_app";

-- Row-level security (ADR-0002), enabled and forced, with the reference policy of
-- platform.isolation_probe on every table.
ALTER TABLE "identity"."account" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "identity"."account" FORCE ROW LEVEL SECURITY;
CREATE POLICY "account_tenant_isolation" ON "identity"."account"
  AS PERMISSIVE FOR ALL TO "phoenix_app"
  USING ("tenant_id" = "platform"."current_tenant_id"())
  WITH CHECK ("tenant_id" = "platform"."current_tenant_id"());

ALTER TABLE "identity"."session" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "identity"."session" FORCE ROW LEVEL SECURITY;
CREATE POLICY "session_tenant_isolation" ON "identity"."session"
  AS PERMISSIVE FOR ALL TO "phoenix_app"
  USING ("tenant_id" = "platform"."current_tenant_id"())
  WITH CHECK ("tenant_id" = "platform"."current_tenant_id"());

ALTER TABLE "identity"."role" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "identity"."role" FORCE ROW LEVEL SECURITY;
CREATE POLICY "role_tenant_isolation" ON "identity"."role"
  AS PERMISSIVE FOR ALL TO "phoenix_app"
  USING ("tenant_id" = "platform"."current_tenant_id"())
  WITH CHECK ("tenant_id" = "platform"."current_tenant_id"());

ALTER TABLE "identity"."role_assignment" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "identity"."role_assignment" FORCE ROW LEVEL SECURITY;
CREATE POLICY "role_assignment_tenant_isolation" ON "identity"."role_assignment"
  AS PERMISSIVE FOR ALL TO "phoenix_app"
  USING ("tenant_id" = "platform"."current_tenant_id"())
  WITH CHECK ("tenant_id" = "platform"."current_tenant_id"());
